    };
    const legacy: TranscodeStatusResponse = {
      job_id: 'j0',
      status: 'running',
      segments: 3,
      playlist_ready: true,
      progress: 42.5,
      master_url: '/hls/j0/master.m3u8?sig=y',
      dash_url: null,
